using System;
using System.Linq;
using System.Reflection;
var t = typeof(Xunit.v3.ITestCaseOrderer);
foreach(var m in t.GetMethods()) {
    Console.WriteLine(m);
    foreach(var g in m.GetGenericArguments()) {
        Console.WriteLine("  constraints: " + string.Join(", ", g.GetGenericParameterConstraints().Select(c => c.FullName)));
        Console.WriteLine("  attrs: " + g.GenericParameterAttributes);
    }
}
EOF
dotnet run 2>&1 | grep -v warning

arguments.new_str:
using Xunit.Sdk;
using Xunit.v3;

namespace MyApp.Tests;

public class AlphabeticalOrderer : ITestCaseOrderer
{
    public IReadOnlyCollection<TTestCase> OrderTestCases<TTestCase>(IReadOnlyCollection<TTestCase> testCases)
        where TTestCase : ITestCase
    {
        return testCases.OrderBy(tc => tc.TestCaseDisplayName).ToList();
    }
}

